"""Build notebooks/08_figures_and_summary.ipynb (thin report: shows SUMMARY.md, figures, tables; no test access)."""

from pathlib import Path

import nbformat as nbf

ROOT = Path(__file__).resolve().parents[1]
nb = nbf.v4.new_notebook()
nb.metadata["kernelspec"] = {"name": "fairness-credit", "display_name": "fairness-credit", "language": "python"}
md, code = nbf.v4.new_markdown_cell, nbf.v4.new_code_cell
nb.cells = [
    md(
        "# 08 Phase 8: figures, tables and summary\n\n**What this shows.** Every figure and table below is regenerated by "
        "`scripts/make_all_figures_tables.py` from the frozen bundle and saved artifacts, with no test-set access. The "
        "soft flags and the honest headline findings come first, as in `artifacts/SUMMARY.md`."
    ),
    code(
        "import sys, subprocess\nfrom pathlib import Path\n"
        "ROOT = Path.cwd().parent if Path.cwd().name == 'notebooks' else Path.cwd()\n"
        "import pandas as pd\nfrom IPython.display import Image, Markdown, display\n"
        "pd.set_option('display.width', 250); pd.set_option('display.max_columns', 60); pd.set_option('display.max_rows', 200)\n"
        "r = subprocess.run([sys.executable, 'scripts/make_all_figures_tables.py'], cwd=ROOT, capture_output=True, text=True)\n"
        "print('regeneration exit code:', r.returncode); print(r.stdout[-600:])\n"
        "display(Markdown((ROOT / 'artifacts' / 'SUMMARY.md').read_text(encoding='utf-8')))"
    ),
    md("## Figures"),
    code(
        "for n in ['pareto_deployable_test', 'reliability_by_gender', 'leakage_before_after', 'tradeoff_sweep_validation', 'fairness_groups', 'taiwan_pareto']:\n"
        "    print(n); display(Image(filename=str(ROOT / 'artifacts' / 'figures' / (n + '.png')), width=900))"
    ),
    md("## Tables"),
    code(
        "T = ROOT / 'artifacts' / 'tables'\n"
        "for n in ['test_results_all_arms.csv', 'val_vs_test.csv', 'leakage_after.csv', 'matched_pair.csv', 'taiwan_test.md']:\n"
        "    print(); print(n)\n"
        "    if n.endswith('.csv'): display(pd.read_csv(T / n).round(4))\n"
        "    else: display(Markdown((T / n).read_text(encoding='utf-8')))"
    ),
]
nbf.write(nb, ROOT / "notebooks" / "08_figures_and_summary.ipynb")
print("written")
